CREATE OR REPLACE TABLE "co2_per_capita_change" AS
WITH b AS (SELECT country, grouping, co2_t_per_person AS t1990 FROM clean_co2_per_capita WHERE year = 1990), l AS (SELECT country, year AS latest_year, co2_t_per_person AS t_latest FROM clean_co2_per_capita QUALIFY row_number() OVER (PARTITION BY country ORDER BY year DESC) = 1), p AS (SELECT country, arg_max(year, co2_t_per_person) AS peak_year, max(co2_t_per_person) AS t_peak FROM clean_co2_per_capita GROUP BY country) SELECT b.country, b.grouping, round(b.t1990, 2) AS t1990, l.latest_year, round(l.t_latest, 2) AS t_latest, round(l.t_latest - b.t1990, 2) AS change_t, round(100 * (l.t_latest / b.t1990 - 1), 1) AS change_pct, p.peak_year, round(p.t_peak, 2) AS t_peak FROM b JOIN l USING (country) JOIN p USING (country) ORDER BY change_pct
